import{_ as o,o as t,c as n,a5 as a}from"./chunks/framework.BjM_ivYE.js";const r="/RBQ/images/app/home-vision.pc.en.png",s="/RBQ/images/app/dashboard-detail.pc.en.png",u=JSON.parse('{"title":"Developer mode","description":"","frontmatter":{"layout":"doc","outline":"deep","title":"Developer mode"},"headers":[],"relativePath":"manual/gui/developer-mode.md","filePath":"manual/gui/developer-mode.md","lastUpdated":1790654982000}'),i={name:"manual/gui/developer-mode.md"};function d(c,e,h,l,p,g){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="developer-mode" tabindex="-1">Developer mode <a class="header-anchor" href="#developer-mode" aria-label="Permalink to &quot;Developer mode&quot;">​</a></h1><p>The app runs at the <strong>operator tier</strong> by default. Turning on developer mode adds diagnostic, configuration and maintenance features to the screens. <strong>Everything that only developer mode opens is collected on this page</strong> — the other pages cover what everyday operation needs.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>Developer mode exposes <strong>commands that move the robot without the usual safeguards</strong> (joint lock, forced postures) and power controls that can cut the connection, the stance or driving. Turn it on only when you need it, and read each warning before you act.</p></div></div><h2 id="turn-on" tabindex="-1">Turning it on and off <a class="header-anchor" href="#turn-on" aria-label="Permalink to &quot;Turning it on and off {#turn-on}&quot;">​</a></h2><ol><li>Tap the profile button at the top right of the hub.</li><li>Turn on the <strong>Developer mode</strong> toggle. The subtitle reads <em>Password required to turn on</em>.</li><li>Type the password in the <strong>Developer mode password</strong> dialog and press <strong>Check</strong>. A wrong password shows <em>Incorrect password</em> and clears the field.</li></ol><p>Turning the toggle off returns to the operator tier immediately.</p><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">WARNING</p><p>The password is <strong>issued individually by Rainbow Robotics</strong>. It is not printed in this manual — do not share the one you were given. To request it, use <a href="/RBQ/manual/support/">Support</a>.</p></div></div><h3 id="by-account" tabindex="-1">When an account sets the tier <a class="header-anchor" href="#by-account" aria-label="Permalink to &quot;When an account sets the tier {#by-account}&quot;">​</a></h3><p>Logging in with an access code (<code>Log in with access code</code> in the profile menu) sets the tier <strong>from your account</strong>. While logged in the profile menu shows the account and its level instead of the Developer mode toggle. Press <code>Log out</code> in the same menu to return to the normal tier.</p><h2 id="what-changes" tabindex="-1">What each screen gains <a class="header-anchor" href="#what-changes" aria-label="Permalink to &quot;What each screen gains {#what-changes}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Screen</th><th>Added in developer mode</th></tr></thead><tbody><tr><td><a href="#control-home">Control home</a></td><td>External-control toggle in the <code>CONTROL INPUT</code> popover</td></tr><tr><td><a href="#motion">Motion commands</a></td><td><strong>AI motion</strong> group (learned gaits) and <strong>Position control</strong> group (forced postures)</td></tr><tr><td><a href="#gamepad">Gamepad</a></td><td>Sensitivity, deadzone, button mapping, external control, developer options, diagnostics, wizard</td></tr><tr><td><a href="#vision">Camera &amp; Vision</a></td><td>Camera calibration (the <code>Vision</code> popover itself is open to everyone)</td></tr><tr><td><a href="#dashboard">Dashboard</a></td><td><strong>Robot</strong> and <strong>Vision</strong> tabs; power added to the summary</td></tr><tr><td><a href="#settings">Settings</a></td><td>Enable camera calibration</td></tr><tr><td><a href="#connection">Connection</a></td><td><code>Connect by address</code> card on Android and iOS · <code>Vision PC IP (optional)</code> field</td></tr><tr><td><a href="#emergency">Emergency stop</a></td><td>Forced recovery through Position control</td></tr><tr><td><a href="#maintenance">Maintenance</a></td><td><strong>The entire screen is developer-only</strong> — <code>Maintenance</code> tile on the hub</td></tr><tr><td>Logs</td><td><strong>Nothing</strong> — this screen does not change with the tier</td></tr></tbody></table><h2 id="control-home" tabindex="-1">Control home <a class="header-anchor" href="#control-home" aria-label="Permalink to &quot;Control home {#control-home}&quot;">​</a></h2><ul><li>The <strong>CONTROL INPUT</strong> popover gains the <strong>External control (SLAM/SDK)</strong> toggle, which hands driving over to an external program. The <code>SLAM</code> chip in the top bar shows while it is on and turns it off again.</li></ul><p>→ <a href="/RBQ/manual/gui/control-home.html">Control home</a></p><h2 id="motion" tabindex="-1">Motion commands — AI motion · Position control <a class="header-anchor" href="#motion" aria-label="Permalink to &quot;Motion commands — AI motion · Position control {#motion}&quot;">​</a></h2><p>The <strong>Select motion</strong> grid gains an <strong>AI motion</strong> group and a <strong>Position control</strong> group.</p><p><strong>AI motion</strong> holds the learned gaits: <code>AI Pronk</code>, <code>AI Bound</code>, <code>AI Pace</code>, <code>AI Run</code>, <code>AI 2Leg L</code>, <code>AI 2Leg R</code>, <code>AI 2Leg F</code> and <code>AI 3Leg HL</code>. They are hidden entirely at the operator level.</p><p><strong>Position control</strong> — <code>Lock Joints</code>, <code>Position Sit</code> and <code>Position Stand</code> — forces a posture without the normal transitions. The same items are in the long-press list under <code>SIT</code>. On wheeled robots the <strong>Precision·Calib</strong> group also offers <code>HIGH SPEED</code>.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>Position control changes posture with no trajectory. Use it <strong>only on flat ground with the robot on the floor</strong>. It exists for cases where the normal recovery does not work.</p></div></div><p>→ <a href="/RBQ/manual/gui/motion-commands.html">Motion commands</a> · <a href="/RBQ/manual/gui/emergency.html">Emergency stop</a></p><h2 id="gamepad" tabindex="-1">Gamepad <a class="header-anchor" href="#gamepad" aria-label="Permalink to &quot;Gamepad {#gamepad}&quot;">​</a></h2><p>The following appear in <strong>App settings › Gamepad</strong>.</p><p><strong>Response</strong></p><ul><li><code>Gamepad sensitivity</code> — input response curve for the physical sticks (separate from the virtual joystick setting).</li><li><code>Deadzone</code> — center ignore range, added on top of the device&#39;s own dead zone.</li></ul><p><strong><code>Button mapping</code></strong> — tap a button on the controller diagram to assign a robot motion to it; the D-pad and stick-center buttons can be mapped too. Mapped buttons are listed under the diagram with an <code>×</code> to remove them. A controller must be connected, and the diagram lights up as you press buttons.</p><p><strong><code>External control (SLAM/SDK)</code></strong> — hands robot control to an external source. The switch reflects the robot&#39;s real state, so it also updates if another client flips it. The same switch is in the <code>CONTROL INPUT</code> popover on the control home.</p><p><strong><code>Developer options</code></strong></p><table tabindex="0"><thead><tr><th>Row</th><th>Effect</th></tr></thead><tbody><tr><td><code>Send all buttons</code></td><td>OFF = only L1/R1 reach the robot (the safe default). ON forwards every button, which is what makes chords such as <strong>L1+B</strong> work. It turns on when you enter developer mode and back off when you return to the normal level</td></tr><tr><td><code>One-stick mode</code></td><td>One-handed operation — swaps only the horizontal axes of the two sticks (vertical stays on each)</td></tr><tr><td><code>Cruise control</code></td><td>R3 starts cruise, D-pad up/down changes speed. Works only during TROT-family gaits</td></tr><tr><td><code>Publish rate — {hz}Hz</code></td><td>Joystick frame rate (40 Hz by default). Lower adds latency, higher adds traffic</td></tr><tr><td><code>Input diagnostics</code> › <code>Open diagnostics</code></td><td>The <code>Gamepad diagnostics</code> screen — <code>Connected devices</code> (name, VID:PID, axes), live <code>Axes (raw)</code> bars and a <code>Button events</code> key-code log. Use it to check an unknown controller before mapping</td></tr><tr><td><code>Mapping Wizard</code> › <code>Start wizard</code></td><td>Follow the prompts to build a profile for this device — for unknown controllers or when the stick layout is wrong</td></tr><tr><td><code>Delete wizard profile</code></td><td>Shown only when the connected device has a wizard profile. Deletes it and returns to auto-detection</td></tr></tbody></table><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p><code>Send all buttons</code> and <code>Cruise control</code> change how the robot responds to button input. After enabling it, try it in an open area first and stay within reach of <code>E-STOP</code>.</p></div></div><p>→ <a href="/RBQ/manual/gui/gamepad.html">Gamepad</a></p><h2 id="vision" tabindex="-1">Camera &amp; Vision <a class="header-anchor" href="#vision" aria-label="Permalink to &quot;Camera &amp; Vision {#vision}&quot;">​</a></h2><p><img src="'+r+'" alt="Vision popover"></p><p>The <code>Vision</code> row on the right card opens the <strong>robot-side vision switches</strong> — that popover is open to everyone; see <a href="/RBQ/manual/gui/camera-vision.html">Camera &amp; Vision</a>. Developer mode adds only the camera calibration entry at its bottom.</p><p>At the bottom of the popover, <code>Camera calibration</code> opens the camera calibration tool; the same entry is under <strong>Robot settings › Calibration › <code>Open camera calibration</code></strong>. Both appear only when camera calibration is enabled in the app <strong>and</strong> the account is at the developer tier. While a run is in progress the labels change to <code>Camera calibration running — tap to cancel</code> / <code>Running — tap to cancel</code>.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>The OAK-D intrinsic calibration makes the robot <strong>walk around by itself for about 10 minutes.</strong> Clear the area before starting it.</p></div></div><p>→ <a href="/RBQ/manual/gui/camera-vision.html">Camera &amp; Vision</a></p><h2 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard {#dashboard}&quot;">​</a></h2><p><img src="'+s+'" alt="Robot state tables"></p><p>Three tabs appear under the title: <strong>Summary</strong>, <strong>Robot</strong> and <strong>Vision</strong>. The summary also gains <strong>Power maintenance ▸</strong> (System card).</p><p><strong>Robot</strong> tab tables:</p><ul><li><strong>Power · PDU</strong> — the title also shows the PDU battery percentage; per rail (<strong>TOTAL</strong>, <strong>BAT L</strong>, <strong>BAT R</strong>, <strong>LEGS</strong>, <strong>ADDON</strong>, <strong>EXTERN</strong>, <strong>CHARGE</strong>): voltage, current, temperature and switch state. On the CHARGE row the switch column names what is active: <strong>Dock</strong> / <strong>Port</strong>.</li><li><strong>Device power · 12V/5V</strong> — ON / OFF of each device rail.</li><li><strong>IMU</strong> — <strong>ANGLE°</strong>, <strong>GYRO (rad/s)</strong>, <strong>ACC (m/s²)</strong> for R(x), P(y), Y(z), with an <strong>IMU calibration ▸</strong> shortcut underneath.</li><li><strong>Joint · JOINT</strong> — one row per joint: <strong>ID</strong>, <strong>STATUS</strong>, <strong>ERR</strong>, <strong>°C B/S</strong> (board / stator), <strong>ANGLE°</strong>. STATUS reads <em>C·H·R</em> — <strong>C</strong> connected (<strong>N</strong> not), <strong>H</strong> homed, <strong>R</strong> running. Green = running and homed, amber = running only, red = otherwise. Temperature turns amber at 60 °C and red at 70 °C.</li></ul><p><strong>Vision</strong> tab — daemon connection, sensor count, the vision program list with <strong>Vision maintenance ▸</strong>, and the <strong>Vision sensors</strong> table (STATUS, RGB / IR / 3D fps, EMIT).</p><p>→ <a href="/RBQ/manual/gui/dashboard.html">Dashboard</a></p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings {#settings}&quot;">​</a></h2><ul><li><strong>Calibration › <code>Enable camera calibration</code></strong> — turning it on shows <code>Open camera calibration</code> below. It runs the jig extrinsic / OAK-D intrinsic procedure; progress appears in the top banner.</li></ul><p>→ <a href="/RBQ/manual/gui/settings.html">Settings</a></p><h2 id="connection" tabindex="-1">Connection <a class="header-anchor" href="#connection" aria-label="Permalink to &quot;Connection {#connection}&quot;">​</a></h2><p>On Android and iOS, <strong>Add robot</strong> gains the <code>Connect by address</code> card (the web build, the desktop app and Steam Deck always show it). A collapsed <code>Vision PC IP (optional)</code> appears under it, for robots whose vision computer has its own address. Leave it blank to use the robot IP. It is saved with the robot IP when you connect.</p><p>→ <a href="/RBQ/manual/gui/connection.html">Connection</a></p><h2 id="emergency" tabindex="-1">Emergency stop — forced recovery <a class="header-anchor" href="#emergency" aria-label="Permalink to &quot;Emergency stop — forced recovery {#emergency}&quot;">​</a></h2><p>The <code>Select motion</code> grid — opened with the dashed <code>Motions</code> button — has a <strong>Position control</strong> group for cases where the normal recovery does not work. <code>Lock Joints</code>, <code>Position Sit</code> and <code>Position Stand</code> force a posture without a trajectory, so use them <strong>only on flat ground with the robot on the floor</strong>. The manual joint-by-joint recovery panel is reserved for internal use.</p><p>→ <a href="/RBQ/manual/gui/emergency.html">Emergency stop</a></p><h2 id="maintenance" tabindex="-1">Maintenance — the whole screen <a class="header-anchor" href="#maintenance" aria-label="Permalink to &quot;Maintenance — the whole screen {#maintenance}&quot;">​</a></h2><p>The <strong>Maintenance</strong> screen is developer-only in its entirety. Without developer mode the <code>Maintenance</code> tile does not appear on the hub, and the route redirects to the control home.</p><p>Everything there can <strong>cut the connection, drop the robot or change how its daemons start.</strong> Read each warning before you press anything.</p><p>→ <a href="/RBQ/manual/gui/maintenance.html">Maintenance</a></p>',56)])])}const b=o(i,[["render",d]]);export{u as __pageData,b as default};
